/* Token Radar: a dark radar-room theme. Ink navy canvas, amber signal, green
   for growth, red for decline. One palette, two radii, two families. */
:root {
  --canvas: #0a0f1a;
  --surface: #111a2c;
  --surface-2: #16233a;
  --ink: #e8eef7;
  --muted: #93a3b8;
  --faint: #5f7089;
  --border: #233350;
  --accent: #f5b942;
  --accent-ink: #1a1405;
  --green: #34d399;
  --red: #f87171;
  --radius-control: 8px;
  --radius-panel: 14px;
  --font-body: system-ui, -apple-system, "Segoe UI", sans-serif;
  --font-num: ui-monospace, "SF Mono", Menlo, Consolas, monospace;
  --s1: 4px; --s2: 8px; --s3: 12px; --s4: 16px; --s5: 24px; --s6: 32px; --s7: 48px;
}

* { box-sizing: border-box; }
html { color-scheme: dark; }
body {
  margin: 0; background: var(--canvas); color: var(--ink);
  font: 400 15px/1.5 var(--font-body); text-wrap: pretty;
}
h1, h2, h3 { margin: 0; letter-spacing: -0.02em; text-wrap: balance; }
h1 { font-size: 32px; line-height: 1.12; font-weight: 700; }
h2 { font-size: 20px; line-height: 1.2; font-weight: 650; }
h3 { font-size: 15px; line-height: 1.25; font-weight: 650; }
p { margin: 0; }
button, input, select { font: inherit; color: inherit; }
button { cursor: pointer; }
a { color: var(--accent); }
.skip { position: absolute; left: -9999px; top: 0; padding: var(--s2) var(--s4); background: var(--surface); border: 1px solid var(--border); z-index: 20; }
.skip:focus { left: var(--s4); top: var(--s4); }
:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; }

.shell { max-width: 1320px; margin: 0 auto; padding: var(--s5) var(--s6) var(--s7); }
.top { display: flex; align-items: flex-start; justify-content: space-between; gap: var(--s5); padding-bottom: var(--s4); border-bottom: 1px solid var(--border); }
.brand { display: flex; align-items: center; gap: var(--s3); }
.mark { width: 14px; height: 14px; border-radius: 50%; background: var(--accent); box-shadow: 0 0 0 4px rgba(245, 185, 66, 0.18); flex: none; }
.brand-name { font-family: var(--font-num); font-size: 13px; letter-spacing: 0.14em; text-transform: uppercase; color: var(--muted); }
.top-meta { display: flex; flex-wrap: wrap; gap: var(--s3); justify-content: flex-end; color: var(--muted); font-size: 13px; }
.top-meta span { white-space: nowrap; }

.lede { display: grid; grid-template-columns: minmax(0, 1.3fr) minmax(300px, 0.7fr); gap: var(--s6); padding: var(--s6) 0 var(--s5); }
.lede p { color: var(--muted); max-width: 62ch; margin-top: var(--s2); }
.lede p b { color: var(--ink); font-weight: 600; }
.facts { display: grid; gap: var(--s2); align-content: start; border-left: 1px solid var(--border); padding-left: var(--s5); }
.fact { display: flex; align-items: baseline; justify-content: space-between; gap: var(--s3); }
.fact b { font-family: var(--font-num); font-size: 15px; font-weight: 600; color: var(--accent); }
.fact span { color: var(--muted); font-size: 13px; }

.spot { display: grid; grid-template-columns: repeat(5, minmax(0, 1fr)); gap: var(--s3); padding-bottom: var(--s5); }
.spot-card { background: var(--surface); border: 1px solid var(--border); border-radius: var(--radius-panel); padding: var(--s4); cursor: pointer; display: grid; gap: var(--s2); text-align: left; }
.spot-card:hover { border-color: var(--accent); }
.spot-card .rank { font-family: var(--font-num); font-size: 12px; color: var(--accent); letter-spacing: 0.08em; }
.spot-card b { font-size: 15px; line-height: 1.3; }
.spot-card .val { font-family: var(--font-num); font-size: 15px; color: var(--green); }
.spot-card .sub { color: var(--muted); font-size: 12px; }
.spot-head { grid-column: 1 / -1; display: flex; align-items: baseline; justify-content: space-between; gap: var(--s3); }
.spot-head span { color: var(--muted); font-size: 13px; }

.controls { display: flex; flex-wrap: wrap; align-items: end; gap: var(--s3); padding: var(--s4) 0; border-top: 1px solid var(--border); }
.field { display: grid; gap: var(--s1); }
.field label { color: var(--muted); font-size: 12px; }
.field input, .field select { min-height: 38px; padding: 0 var(--s3); border: 1px solid var(--border); border-radius: var(--radius-control); background: var(--surface); min-width: 170px; color: var(--ink); }
.field input { min-width: 260px; }
.check { display: flex; align-items: center; gap: var(--s2); min-height: 38px; color: var(--muted); font-size: 13px; cursor: pointer; }
.check input { width: 16px; height: 16px; accent-color: var(--accent); }
.tabs { display: flex; gap: var(--s1); padding: 3px; border: 1px solid var(--border); border-radius: var(--radius-control); background: var(--surface); }
.tabs button { min-height: 32px; padding: 0 var(--s3); border: 0; border-radius: 6px; background: transparent; color: var(--muted); }
.tabs button[aria-pressed="true"] { background: var(--accent); color: var(--accent-ink); font-weight: 600; }
.count { margin-left: auto; color: var(--muted); font-size: 13px; align-self: center; }

.panel { background: var(--surface); border: 1px solid var(--border); border-radius: var(--radius-panel); overflow: hidden; }
.table-wrap { overflow-x: auto; }
table { width: 100%; border-collapse: collapse; font-size: 14px; }
th, td { padding: var(--s3); border-bottom: 1px solid var(--border); text-align: left; vertical-align: middle; }
tbody tr:last-child td { border-bottom: 0; }
th { color: var(--muted); font-size: 12px; font-weight: 500; white-space: nowrap; }
th button { display: inline-flex; align-items: center; gap: var(--s1); border: 0; background: none; padding: 0; color: inherit; font: inherit; }
th button:hover { color: var(--ink); }
tbody tr { cursor: pointer; }
tbody tr:hover { background: var(--surface-2); }
tbody tr[data-selected="true"] { background: var(--surface-2); box-shadow: inset 3px 0 0 var(--accent); }
.num { font-family: var(--font-num); font-variant-numeric: tabular-nums; white-space: nowrap; }
.name { display: grid; gap: 2px; }
.name b { font-weight: 600; }
.sub { color: var(--muted); font-size: 12px; }
.pos { color: var(--green); }
.neg { color: var(--red); }
.bar { width: 120px; height: 6px; border-radius: 3px; background: var(--border); overflow: hidden; }
.bar i { display: block; height: 100%; background: var(--accent); }
.implied { display: flex; align-items: center; gap: var(--s2); }
.badge { display: inline-flex; align-items: center; gap: 6px; color: var(--muted); font-size: 12px; white-space: nowrap; }
.badge::before { content: ""; width: 6px; height: 6px; border-radius: 50%; background: var(--accent); }
.badge.live::before { background: var(--green); }
.watch { display: inline-block; margin-left: 6px; padding: 1px 6px; border: 1px solid var(--accent); border-radius: 999px; color: var(--accent); font-size: 11px; font-family: var(--font-num); vertical-align: middle; }

.model { margin-top: var(--s4); padding: var(--s5); display: grid; gap: var(--s3); }
.formula { font-family: var(--font-num); font-size: 13px; line-height: 1.7; color: var(--muted); overflow-wrap: anywhere; }
.model table { font-size: 13px; }
.model th, .model td { padding: var(--s2) var(--s3); }
.footnote { margin-top: var(--s4); color: var(--faint); font-size: 12px; }
.empty { padding: var(--s7) var(--s5); text-align: center; display: grid; gap: var(--s3); justify-items: center; }
.empty p { color: var(--muted); }
.button { min-height: 38px; padding: 0 var(--s4); border: 1px solid var(--border); border-radius: var(--radius-control); background: var(--surface); }
.button.primary { background: var(--accent); border-color: var(--accent); color: var(--accent-ink); font-weight: 600; }

.detail { position: fixed; top: 0; right: 0; bottom: 0; width: min(560px, 94vw); z-index: 10; background: var(--surface); color: var(--ink); border: 0; border-left: 1px solid var(--border); padding: var(--s5); overflow-y: auto; margin: 0 0 0 auto; max-height: 100%; }
.detail::backdrop { background: rgba(4, 8, 16, 0.6); }
.detail-head { display: flex; align-items: start; justify-content: space-between; gap: var(--s4); }
.detail-head > div { min-width: 0; }
.detail-head .sub { overflow-wrap: anywhere; }
.close { flex: none; min-width: 32px; min-height: 32px; padding: 0 var(--s2); white-space: nowrap; border: 1px solid var(--border); border-radius: var(--radius-control); background: var(--surface); color: var(--ink); }
.detail h2 { margin-top: var(--s1); }
.detail .sub { margin-top: var(--s1); }
.detail-section { margin-top: var(--s5); padding-top: var(--s4); border-top: 1px solid var(--border); }
.detail-section h3 { margin-bottom: var(--s2); }
.equation { display: grid; gap: var(--s2); font-family: var(--font-num); font-size: 13px; }
.equation div { display: flex; justify-content: space-between; gap: var(--s3); }
.equation span { color: var(--muted); }
.steps { margin: 0; padding-left: var(--s5); display: grid; gap: var(--s3); }
.steps li { padding-left: var(--s1); }
.steps b { display: block; font-weight: 500; }
.cost { color: var(--muted); font-size: 12px; font-family: var(--font-num); }

@media (max-width: 1000px) {
  .spot { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .spot-head { grid-column: 1 / -1; }
}
@media (max-width: 900px) {
  .shell { padding: var(--s4); }
  .lede { grid-template-columns: 1fr; gap: var(--s4); }
  .facts { border-left: 0; border-top: 1px solid var(--border); padding-left: 0; padding-top: var(--s4); }
  .field input { min-width: 0; width: 100%; }
  .spot { grid-template-columns: 1fr; }
}
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { transition-duration: 0.01ms !important; animation-duration: 0.01ms !important; animation-iteration-count: 1 !important; }
}
